1. # profiles/k3s-agent.nix — generic k3s worker (agent) role.
2. #
3. # All current agents join the s145-rooted cluster (s145 is the only
4. # control-plane). Host-specific identity (nodeName, nodeIP) is set in the
5. # host's configuration.nix.
6. #
7. # Tiny (1 GB) nodes should import profiles/k3s-agent-tiny.nix instead,
8. # which layers max-pods=10 and zramSwap on top of this profile.
9. #
10. # Depends on: profiles/tailscale.nix (flannel uses tailscale0)
11. { config, lib, ... }:
12. 
13. let
14.   clusterSecretsFile = ../secrets/k3s/secrets.yaml;
15.   hasClusterSecretsFile = builtins.pathExists clusterSecretsFile;
16. in
17. {
18.   services.k3s = lib.mkIf hasClusterSecretsFile {
19.     enable = true;
20.     role = "agent";
21.     serverAddr = "https://100.69.231.117:6443"; # s145 (Tailscale IP)
22.     tokenFile = config.sops.secrets."k3s-token".path;
23.     extraFlags = [
24.       "--flannel-iface=tailscale0"
25.     ];
26.   };
27. 
28.   # Ensure k3s starts after Tailscale is up
29.   systemd.services.k3s = lib.mkIf hasClusterSecretsFile {
30.     after = [ "tailscaled.service" ];
31.     wants = [ "tailscaled.service" ];
32.   };
33. }
