197.   # so, k3s is a complicated thing to package
198.   # This derivation attempts to avoid including any random binaries from the
199.   # internet. k3s-root is _mostly_ binaries built to be bundled in k3s (which
200.   # we don't care about doing, we can add those as build or runtime
201.   # dependencies using a real package manager).
202.   # In addition to those binaries, it's also configuration though (right now
203.   # mostly strongswan configuration), and k3s does use those files.
204.   # As such, we download it in order to grab 'etc' and bundle it into the final
205.   # k3s binary.
206.   k3sRoot = fetchzip {
207.     # Note: marked as apache 2.0 license
208.     url = "https://github.com/k3s-io/k3s-root/releases/download/v${k3sRootVersion}/k3s-root-amd64.tar";
209.     sha256 = k3sRootSha256;
210.     stripRoot = false;
211.   };
212.   k3sCNIPlugins =
213.     (buildGoModule rec {
214.       pname = "k3s-cni-plugins";
215.       version = k3sCNIVersion;
216.       vendorHash = null;
217. 
218.       subPackages = [ "." ];
219. 
220.       src = fetchFromGitHub {
221.         owner = "rancher";
222.         repo = "plugins";
223.         rev = "v${version}";
224.         sha256 = k3sCNISha256;
225.       };
226. 
227.       postInstall = ''
228.         mv $out/bin/plugins $out/bin/cni
229.       '';
230. 
231.       meta = baseMeta // {
232.         description = "CNI plugins, as patched by rancher for k3s";
233.       };
234.     }).overrideAttrs
235.       overrideCniPluginsAttrs;
236.   # Grab this separately from a build because it's used by both stages of the
237.   # k3s build.
238.   k3sRepo = fetchgit {
239.     url = "https://github.com/k3s-io/k3s";
240.     rev = "v${k3sVersion}";
241.     sha256 = k3sRepoSha256;
242.   };
243. 
244.   # Modify the k3s installer script so that we can let it install only
245.   # killall.sh
246.   k3sKillallSh = runCommand "k3s-killall.sh" { } ''
247.     # Copy the upstream k3s install script except for the last lines that
248.     # actually run the install process
249.     sed --quiet '/# --- run the install process --/q;p' ${k3sRepo}/install.sh > install.sh
250. 
251.     # Let killall expect "containerd-shim" in the Nix store
252.     substituteInPlace install.sh \
253.       --replace-fail '"''${K3S_DATA_DIR}"' "" \
254.       --replace-fail '/data/[^/]*/bin/containerd-shim' \
255.         '/nix/store/[^/]*k3s-containerd[^/]*/bin/containerd-shim'
256. 
257.     remove_matching_line() {
258.       line_to_delete=$(grep -n "$1" install.sh | cut -d : -f 1 || true)
259.       if [ -z $line_to_delete ]; then
260.         echo "failed to find expression \"$1\" in k3s installer script (install.sh)"
261.         exit 1
262.       fi
263.       sed -i "''${line_to_delete}d" install.sh
264.     }
265. 
266.     # Don't change mode and owner of killall
267.     remove_matching_line "chmod.*KILLALL_K3S_SH"
268.     remove_matching_line "chown.*KILLALL_K3S_SH"
269. 
270.     # Execute only the "create_killall" function of the installer script
271.     sed -i '$acreate_killall' install.sh
272. 
273.     KILLALL_K3S_SH=$out bash install.sh
274.   '';
