7. let
8.   cfg = config.services.k3s;
9.   baseModule = mkRancherModule {
10.     name = "k3s";
11.     extraBinFlags =
12.       (lib.optional cfg.clusterInit "--cluster-init")
13.       ++ (lib.optional cfg.disableAgent "--disable-agent");
