26. {
27.   imports = [ (removeOption [ "docker" ] "k3s docker option is no longer supported.") ];
28. 
29.   # interface
30. 
31.   options.services.k3s = lib.recursiveUpdate baseModule.options {
32. 
33.     # option overrides
34. 
35.     role.description = ''
36.       Whether k3s should run as a server or agent.
37. 
38.       If it's a server:
39. 
40.       - By default it also runs workloads as an agent.
41.       - Starts by default as a standalone server using an embedded sqlite datastore.
42.       - Configure `clusterInit = true` to switch over to embedded etcd datastore and enable HA mode.
43.       - Configure `serverAddr` to join an already-initialized HA cluster.
44. 
45.       If it's an agent:
46. 
47.       - `serverAddr` is required.
48.     '';
49. 
50.     serverAddr.description = ''
51.       The k3s server to connect to.
52. 
53.       Servers and agents need to communicate each other. Read
54.       [the networking docs](https://rancher.com/docs/k3s/latest/en/installation/installation-requirements/#networking)
55.       to know how to configure the firewall.
56.     '';
57. 
58.     disable.description = ''
59.       Disable default components, see the [K3s documentation](https://docs.k3s.io/installation/packaged-components#using-the---disable-flag).
60.     '';
61. 
62.     images = {
63.       example = lib.literalExpression ''
64.         [
65.           (pkgs.dockerTools.pullImage {
66.             imageName = "docker.io/bitnami/keycloak";
67.             imageDigest = "sha256:714dfadc66a8e3adea6609bda350345bd3711657b7ef3cf2e8015b526bac2d6b";
68.             hash = "REDACTED";
69.             finalImageTag = "21.1.2-debian-11-r0";
70.           })
71. 
72.           config.services.k3s.package.airgap-images
73.         ]
74.       '';
75.       description = ''
76.         List of derivations that provide container images.
77.         All images are linked to {file}`${baseModule.paths.imageDir}` before k3s starts and are consequently imported
78.         by the k3s agent. Consider importing the k3s airgap images archive of the k3s package in
79.         use, if you want to pre-provision this node with all k3s container images. This option
80.         only makes sense on nodes with an enabled agent.
81.       '';
82.     };
83. 
84.     # k3s-specific options
85. 
86.     clusterInit = lib.mkOption {
87.       type = lib.types.bool;
88.       default = false;
89.       description = ''
90.         Initialize HA cluster using an embedded etcd datastore.
91. 
92.         If this option is `false` and `role` is `server`
93. 
94.         On a server that was using the default embedded sqlite backend,
95.         enabling this option will migrate to an embedded etcd DB.
96. 
97.         If an HA cluster using the embedded etcd datastore was already initialized,
98.         this option has no effect.
99. 
100.         This option only makes sense in a server that is not connecting to another server.
101. 
102.         If you are configuring an HA cluster with an embedded etcd,
103.         the 1st server must have `clusterInit = true`
104.         and other servers must connect to it using `serverAddr`.
105.       '';
106.     };
107. 
108.     disableAgent = lib.mkOption {
109.       type = lib.types.bool;
110.       default = false;
111.       description = "Only run the server. This option only makes sense for a server.";
112.     };
113.   };
114. 
115.   # implementation
116. 
117.   config = lib.mkIf cfg.enable (
118.     lib.mkMerge [
119.       baseModule.config
120.       {
121.         warnings =
122.           lib.optional (cfg.disableAgent && cfg.images != [ ])
123.             "k3s: Images are only imported on nodes with an enabled agent, they will be ignored by this node.";
124. 
125.         assertions = [
126.           {
127.             assertion = cfg.role == "agent" -> !cfg.disableAgent;
128.             message = "k3s: disableAgent must be false if role is 'agent'";
129.           }
130.           {
131.             assertion = cfg.role == "agent" -> !cfg.clusterInit;
132.             message = "k3s: clusterInit must be false if role is 'agent'";
133.           }
134.         ];
135.       }
136.     ]
137.   );
138. }
